'use strict';

const $=(s,el=document)=>el.querySelector(s);
const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const app=$('#app');
const STORAGE='nikah_app_5_1_state';
const LEGACY='nikah_app_5_0_state';


const defaults={
 session:false,route:'home',auth:{mode:'register',pending:null},
 user:{id:'me',email:'',phone:'',firstName:'',lastName:'',dob:'',gender:'',seeking:'',country:'Türkiye',city:'Ankara',languages:['Türkçe'],about:'',intent:'Evliliğe hazırım',children:'Kararsız',family:'Önemli',relocation:'Uygun',education:'',job:'',photo:'',selfieVerified:false,identityVerified:false,phoneVerified:false,emailVerified:false,profileComplete:false,onboardingStep:1,terms:false,privacy:false,ageConfirmed:false,compat:{communication:'direct',planning:'planned',social:'balanced',conflict:'calm',money:'planned'}},
 preferences:{minAge:24,maxAge:45,countries:['Türkiye','Endonezya'],distance:'Global',intent:'Evliliğe hazırım',children:'Fark etmez',verifiedOnly:false,dealbreakers:{age:true,intent:true,children:false,region:false}},
 liked:[],passed:[],matches:[],blocked:[],reports:[],messages:{},translatedProfiles:{},likeNotes:{},verificationRequests:[],callHistory:[],safety:{trustedContact:''},matchIds:{},advisory:{requests:[],packages:null,selectedPackage:''},ui:{loading:false},
 marriage:{stage:0,documents:{passport:false,birth:false,single:false,apostille:false,translation:false,kua:false}},
 settings:{language:'tr',translation:true,discoverable:true,notifications:true,verifiedChatsOnly:false,photoPrivacy:true,safetyCheckin:true,qualityMode:true}
};


function deepMerge(target,src){if(!src||typeof src!=='object')return target;for(const k of Object.keys(src)){if(src[k]&&typeof src[k]==='object'&&!Array.isArray(src[k])&&target[k]&&typeof target[k]==='object'&&!Array.isArray(target[k]))deepMerge(target[k],src[k]);else target[k]=src[k]}return target}
function load(){try{const raw=localStorage.getItem(STORAGE)||localStorage.getItem(LEGACY)||'{}';return deepMerge(structuredClone(defaults),JSON.parse(raw))}catch{return structuredClone(defaults)}}
let state=load();
const api=NikahApi;
let profiles=[];      // discovery candidates (from api.discover.list)
let matchProfiles=[]; // active matches with partner summary (from api.matches.list)
let unsubChat=null;const loadedChats=new Set();
let stats=null;
async function refreshStats(){try{stats=await api.stats()}catch{}}
const KIND_RANK={member:0,team:1,showcase:2};
function kindRank(p){return KIND_RANK[p.kind||'member']??0}
function kindBadge(p){if(p.kind==='showcase')return `<span class="badge kind-showcase">◌ ${ax('showcase_badge')}</span>`;if(p.kind==='team')return `<span class="badge kind-team">★ ${ax('team_badge')}</span>`;return ''}
function pct(n){return '%'+n}
function statsCard(compact=false){
 if(!stats)return '';const quiet=!stats.members&&!stats.new_this_week;
 const cell=(v,k)=>`<div class="stat"><strong>${v}</strong><span>${ax(k)}</span></div>`;
 return `<div class="card stats-card${compact?' compact':''}"><h3>${ax('stats_title')}</h3>${quiet?`<p class="muted">${ax('stats_empty')}</p>`:''}<div class="stats-grid">${!quiet?cell(stats.members,'stats_members')+cell(stats.new_this_week,'stats_new_week')+cell(stats.verified,'stats_verified'):''}${cell(stats.team||0,'stats_team')}${cell(stats.showcase||0,'stats_showcase')}${stats.founders_left?cell(stats.founders_left,'stats_founders_left'):''}</div></div>`;
}
function verificationStatusText(){const u=state.user;if(u.selfieVerified&&u.identityVerified)return {cls:'ok',text:ax('verify_status_approved')};const st=u.verificationStatus||'';
 if(/DOB/i.test(st))return {cls:'warn',text:ax('verify_status_dob')};if(st==='In Review')return {cls:'warn',text:ax('verify_status_in_review')};if(st==='Declined')return {cls:'warn',text:ax('verify_status_declined')};if(['In Progress','Not Started','Resubmitted'].includes(st))return {cls:'warn',text:ax('verify_status_in_progress')};return null}
function verificationBlock(){const st=verificationStatusText();const done=state.user.selfieVerified&&state.user.identityVerified;
 return `<div class="callout verify-block"><b>${ax('verify_title')}</b>${st?`<div><span class="badge ${st.cls}">${st.text}</span></div>`:`<p class="muted">${tr('verification_copy')}</p>`}${done?'':`<div class="field-inline" style="margin-top:8px"><button type="button" class="btn small ${st&&st.cls==='warn'&&st.text!==ax('verify_status_declined')?'secondary':''}" id="startVerification">${st&&st.text===ax('verify_status_declined')?ax('verify_retry'):ax('verify_start')}</button></div>`}${api.live?'':`<p class="muted" style="margin-top:6px">${ax('verify_demo_note')}</p>`}</div>`}
function verificationModal(){const m=modal(`<h2>${ax('verify_title')}</h2><p class="muted">${ax('verify_consent_copy')}</p><label class="checkline"><input type="checkbox" id="verifyConsent">${ax('verify_consent_check')}</label><p class="muted"><a href="/legal/consent" target="_blank" rel="noopener">${legalDoc('consent',state.settings.language).title} ↗</a></p><div class="field-inline" style="margin-top:12px"><button class="btn" id="verifyGo" disabled>${ax('verify_start')}</button><button class="btn secondary" data-close>${tr('cancel')}</button></div>`);
 const cb=$('#verifyConsent',m),go=$('#verifyGo',m);cb.onchange=()=>{go.disabled=!cb.checked};
 go.onclick=async()=>{go.disabled=true;try{const r=await api.profile.requestVerification();if(r&&r.url){location.href=r.url;return}state.user.verificationStatus='Approved';save();m.remove();toast(ax('verify_status_approved'));render()}catch(e){go.disabled=false;toast(e.message||ax('error_generic'))}}}
function showcaseModal(id){const p=findProfile(id);if(!p)return;const disc=stats?.founder_discount_pct;
 const m=modal(`<span class="badge kind-showcase">◌ ${ax('showcase_badge')}</span><h2>${ax('showcase_title')}</h2><p class="muted">${ax('showcase_copy')}</p>${disc&&stats?.founders_left?`<div class="callout"><b>${ax('founder_badge')}</b><p>${ax('founder_reserved',{pct:pct(disc)})}</p></div>`:''}<div class="field-inline" style="margin-top:12px"><button class="btn" data-skip-showcase="${id}">${tr('keep_discovering')}</button><button class="btn secondary" data-close>${tr('close')}</button></div>`);
 $('[data-skip-showcase]',m).onclick=()=>{if(!state.passed.includes(id))state.passed.push(id);save();api.discover.pass(id).catch(()=>{});m.remove();render()};
}
function findProfile(id){return profiles.find(x=>x.id===id)||matchProfiles.find(x=>x.id===id)}
function chatKey(p){return p.matchId||state.matchIds[p.id]||p.id}
function homeLang(p){return p.lang||(homeLang(p))}
function money(cents,cur){try{return new Intl.NumberFormat(undefined,{style:'currency',currency:cur||'USD',maximumFractionDigits:0}).format((cents||0)/100)}catch{return ((cents||0)/100)+' '+(cur||'USD')}}
const ROUTES=['discover','matches','marriage','profile','settings','safety'];
function routePath(route){return route==='home'?'/':'/'+route.replace(':','/')}
function routeFromLocation(){const seg=location.pathname.replace(/^\/+|\/+$/g,'');if(!seg)return 'home';const [a,b]=seg.split('/');if(a==='chat'&&b)return 'chat:'+b;if(a==='legal')return 'legal:'+(LEGAL_DOCS.includes((b||'').replace(/\.tr$/,''))?b:'terms');return ROUTES.includes(a)?a:'home'}
window.addEventListener('popstate',()=>{state.route=routeFromLocation();save();render()});
async function syncProfile(){if(!api.live||!state.session)return;try{await api.profile.save({user:state.user,preferences:state.preferences,settings:state.settings,safety:state.safety})}catch(e){toast(e.message||ax('error_generic'))}}
async function refreshDiscover(){try{profiles=await api.discover.list()}catch(e){console.error(e)}}
async function refreshMatches(){try{matchProfiles=await api.matches.list();if(api.live)state.matches=matchProfiles.map(p=>p.id);matchProfiles.forEach(p=>{if(p.matchId)state.matchIds[p.id]=p.matchId})}catch(e){console.error(e)}}
async function refreshAdvisory(){try{const [pk,reqs]=await Promise.all([api.advisory.packages(),api.advisory.list()]);state.advisory.packages=pk;state.advisory.requests=reqs;if(!state.advisory.selectedPackage)state.advisory.selectedPackage=(pk[1]||pk[0]||{}).code||''}catch(e){console.error(e)}}
async function refreshAll(){if(api.live&&!state.user.profileComplete){await Promise.all([refreshAdvisory(),refreshStats()]);return}await Promise.all([refreshDiscover(),refreshMatches(),refreshAdvisory(),refreshStats()])}
async function afterLogin(){
 state.session=true;
 if(api.live){
  const data=await api.profile.load();
  if(data){Object.assign(state.user,data.user);if(data.preferences)Object.assign(state.preferences,data.preferences);if(data.settings)Object.assign(state.settings,data.settings);if(data.safety)Object.assign(state.safety,data.safety);if(data.journey)Object.assign(state.marriage,data.journey)}
  else{const keep={email:state.user.email,phone:state.user.phone,phoneVerified:state.user.phoneVerified,emailVerified:state.user.emailVerified};const lang=state.settings.language;state.user={...structuredClone(defaults.user),...keep};state.liked=[];state.passed=[];state.matches=[];state.messages={};state.matchIds={};state.likeNotes={};state.translatedProfiles={};state.advisory.requests=[];state.settings.language=lang}
 }
 await refreshAll();save();
}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true}catch(err){console.error('Nikah.App storage error',err);return false}}
function toast(msg){const e=document.createElement('div');e.className='toast';e.textContent=msg;$('#toast-root').appendChild(e);setTimeout(()=>e.remove(),2800)}
function setRoute(route,{replace=false}={}){state.route=route;save();try{history[replace?'replaceState':'pushState']({route},'',routePath(route))}catch{}render();window.scrollTo({top:0,behavior:'smooth'})}
function profilePct(){const u=state.user;const keys=['firstName','dob','gender','seeking','country','city','about','intent'];let n=keys.filter(k=>u[k]).length;n+=u.photo?1:0;n+=u.phoneVerified?1:0;n+=u.terms&&u.privacy&&u.ageConfirmed?1:0;return Math.round(n/11*100)}

function commonLanguage(p){const mine=new Set((state.user.languages||[]).map(x=>x.toLowerCase()));return (p.languages||[]).some(x=>mine.has(String(x).toLowerCase())||x==='English')}
function regionMatch(p){if(state.preferences.distance==='Global')return true;if(state.preferences.distance==='Ülkem')return p.country===state.user.country;if(state.preferences.distance==='Şehrim')return p.country===state.user.country&&p.city===state.user.city;return true}
function eligibleProfile(p){
 if(!genderOk(state.user,p))return false;
 if(p.kind==='team')return !state.blocked.includes(p.id)&&!state.passed.includes(p.id)&&!state.liked.includes(p.id); // team profiles bypass dealbreakers
 if(state.preferences.verifiedOnly&&!p.verified)return false;
 const db=state.preferences.dealbreakers||{};
 if(db.age&&(p.age<state.preferences.minAge||p.age>state.preferences.maxAge))return false;
 if(db.intent&&state.preferences.intent!=='Fark etmez'&&p.intent!==state.preferences.intent)return false;
 if(db.children&&state.preferences.children&&state.preferences.children!=='Fark etmez'&&p.children!==state.preferences.children)return false;
 if(db.region&&!regionMatch(p))return false;
 return !state.blocked.includes(p.id)&&!state.passed.includes(p.id)&&!state.liked.includes(p.id);
}
function compatibilityData(p){
 const u=state.user,uc=u.compat||{},pc=p.compat||{};
 const values=Math.round(45+(p.intent===u.intent?25:0)+(p.children===u.children?15:0)+(p.family===u.family?15:Math.abs(['Daha bağımsız','Önemli','Çok önemli'].indexOf(p.family)-['Daha bağımsız','Önemli','Çok önemli'].indexOf(u.family))<=1?8:0));
 const family=Math.round(55+(p.family===u.family?28:12)+(p.children===u.children?17:0));
 const lifestyle=Math.round(48+(p.relocation===u.relocation?20:8)+(pc.planning===uc.planning?14:5)+(pc.social===uc.social?12:5)+(pc.money===uc.money?6:2));
 const communication=Math.round(52+(pc.communication===uc.communication?22:8)+(pc.conflict===uc.conflict?16:6)+(commonLanguage(p)?10:0));
 const factors=[values,family,lifestyle,communication].map(x=>Math.max(50,Math.min(99,x)));
 const score=Math.round(factors[0]*.30+factors[1]*.25+factors[2]*.25+factors[3]*.20+(p.verified?3:0));
 const reasons=[];if(p.intent===u.intent)reasons.push('match_reason_intent');if(p.family===u.family)reasons.push('match_reason_family');if(p.children===u.children)reasons.push('match_reason_children');if(p.relocation===u.relocation)reasons.push('match_reason_relocation');if(commonLanguage(p))reasons.push('match_reason_language');if(regionMatch(p))reasons.push('match_reason_region');
 return {score:Math.min(99,score),factors,reasons:reasons.slice(0,4)};
}
function compatScore(p){return compatibilityData(p).score}
function trustScore(p){return Math.min(100,45+(p.verified?30:0)+15+10)}
function conversationStarters(p){
 const lang=state.settings.language,first=p.prompts?.[0]?.[1],answer=(first&&(first[lang]||first.en))||'';
 const name=p.name;
 const sets={
  tr:[`${name}, profilindeki “${answer}” cevabı dikkatimi çekti. Bunu senin için önemli yapan ne?`,`${p.city}’de sakin bir hafta sonu için en sevdiğin yer neresi?`,`Evlilikte iki kişinin iyi bir takım olması sence en çok neye bağlı?`],
  id:[`${name}, jawabanmu “${answer}” menarik perhatianku. Mengapa itu penting bagimu?`,`Tempat favoritmu untuk akhir pekan yang tenang di ${p.city} apa?`,`Menurutmu apa yang paling membuat dua orang menjadi tim yang baik dalam pernikahan?`],
  en:[`${name}, your answer “${answer}” stood out to me. What makes that important to you?`,`What is your favorite place for a calm weekend in ${p.city}?`,`What do you think matters most for two people to become a strong team in marriage?`],
  zh:[`${name}，你资料里的“${answer}”让我很有共鸣。为什么这对你很重要？`,`在${p.city}，你最喜欢去哪里度过安静的周末？`,`你觉得婚姻里两个人成为好队友最重要的是什么？`],
  th:[`${name} คำตอบ “${answer}” ในโปรไฟล์ของคุณน่าสนใจมาก ทำไมสิ่งนี้ถึงสำคัญสำหรับคุณ?`,`สถานที่โปรดสำหรับวันหยุดเงียบๆ ใน ${p.city} คือที่ไหน?`,`คุณคิดว่าอะไรสำคัญที่สุดที่ทำให้คนสองคนเป็นทีมที่ดีในชีวิตแต่งงาน?`]
 };
 return sets[lang]||sets.en;
}
function compressProfilePhoto(file,done){
 const fallback=()=>{const r=new FileReader();r.onload=()=>done(r.result);r.readAsDataURL(file)};
 if(!file||!file.type?.startsWith('image/'))return;
 const reader=new FileReader();
 reader.onload=()=>{const img=new Image();img.onload=()=>{try{const max=1000,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.drawImage(img,0,0,w,h);done(c.toDataURL('image/jpeg',.82))}catch{fallback()}};img.onerror=fallback;img.src=reader.result};reader.onerror=fallback;reader.readAsDataURL(file)
}

async function confirmLike(id,note='',isSuper=false){
 const p=findProfile(id);if(!p)return;
 let res;try{res=await api.discover.like(id,note,isSuper?'super':'like')}catch(e){return toast(e.message||ax('error_generic'))}
 if(res.showcase)return showcaseModal(id);
 if(!state.liked.includes(id))state.liked.push(id);if(note)state.likeNotes[id]=note;
 if(res.matched&&!state.matches.includes(id)){
  state.matches.push(id);if(res.matchId){state.matchIds[id]=res.matchId;p.matchId=res.matchId}matchProfiles=[{...p},...matchProfiles.filter(x=>x.id!==id)];save();if(api.live)refreshDiscover().then(render);
  const m=modal(`<span class="badge brand">${tr('new_match')}</span><h2>🎉 ${esc(p.name)} ${tr('matched_with')}</h2><p class="muted">${tr('mutual_copy')}</p>${note?`<div class="callout"><b>${nx('message_with_like')}</b><p>${esc(note)}</p></div>`:''}<div class="field-inline"><button class="btn" data-open-chat="${id}">${tr('send_message')}</button><button class="btn secondary" data-close>${tr('keep_discovering')}</button></div>`);
  m.addEventListener('click',e=>{if(e.target.dataset.openChat){m.remove();setRoute('chat:'+id)}else if(e.target===m||e.target.matches('[data-close]'))setTimeout(render,0)});
 } else {save();toast(isSuper?tr('super_sent'):tr('like_sent'));if(api.live)await refreshDiscover();render()}
}
function meaningfulLikeModal(id,isSuper=false){
 const p=findProfile(id);if(!p)return;if(p.kind==='showcase')return showcaseModal(id);const starters=conversationStarters(p);
 const m=modal(`<span class="badge brand">${isSuper?'★ '+tr('super'):nx('message_with_like')}</span><h2>${esc(p.name)}</h2><p class="muted">${nx('message_optional')}</p><div class="starter-list">${starters.map((x,i)=>`<button class="starter" data-starter="${i}">${esc(x)}</button>`).join('')}</div><textarea id="likeNote" class="like-note" maxlength="280" rows="4" placeholder="${esc(nx('message_optional'))}"></textarea><div class="field-inline" style="margin-top:12px"><button class="btn" id="confirmLike">${nx('send_like')}</button><button class="btn secondary" data-close>${tr('cancel')}</button></div>`);
 $$('.starter',m).forEach(b=>b.onclick=()=>{$('#likeNote',m).value=starters[Number(b.dataset.starter)]});
 $('#confirmLike',m).onclick=()=>{const note=$('#likeNote',m).value.trim();m.remove();confirmLike(id,note,isSuper)};
}
function secureCallModal(id,kind){const p=findProfile(id);const m=modal(`<span class="badge ok">${nx('secure_call')}</span><h2>${kind==='video'?'▣ '+nx('video_call'):'◉ '+nx('voice_call')} • ${esc(p.name)}</h2><p class="muted">${nx('call_demo')}</p><div class="secure-call-demo"><div class="avatar big">${initials(p.name)}</div><b>${esc(p.name)}</b><span>${p.verified?'✓ '+tr('verified_profile'):tr('verification_pending')}</span></div><button class="btn secondary" data-close>${tr('close')}</button>`);state.callHistory.push({id,kind,at:new Date().toISOString()});save();api.safety.logCall(p.matchId||state.matchIds[id],kind).catch(()=>{});return m}
function safetyView(){
 const myTrust=Math.min(100,35+(state.user.phoneVerified?20:0)+(state.user.selfieVerified?25:0)+(state.user.identityVerified?20:0));
 const row=(key,copy,setting)=>`<div class="safety-feature"><div><b>${nx(key)}</b><p>${nx(copy)}</p></div><span class="switch ${state.settings[setting]?'on':''}" data-setting-toggle="${setting}" role="switch" aria-checked="${state.settings[setting]}"></span></div>`;
 return topShell(`<div class="page-head"><div><div class="eyebrow">${nx('trust_nav')}</div><h1>${nx('trust_title')}</h1><p>${nx('trust_lead')}</p></div></div><div class="safety-grid"><section class="card trust-score-card"><div class="trust-gauge"><strong>${myTrust}</strong><span>/100</span></div><div><h2>${nx('trust_score')}</h2><p class="muted">${nx('trust_score_copy')}</p><span class="badge ${myTrust>=75?'ok':'warn'}">${nx('trust_level')}: ${nx(myTrust>=75?'high':'medium')}</span></div></section><section class="card"><h2>${nx('verification')}</h2>${row('verified_chat','verified_chat_copy','verifiedChatsOnly')}${row('photo_privacy','photo_privacy_copy','photoPrivacy')}</section><section class="card"><h2>${nx('meeting_safety')}</h2>${row('safe_checkin','safe_checkin_copy','safetyCheckin')}<div class="field" style="margin-top:14px"><label>${nx('trusted_contact')}</label><input id="trustedContact" value="${esc(state.safety.trustedContact||'')}" placeholder="+90 / email"><small>${nx('trusted_contact_copy')}</small></div><button class="btn secondary small" id="saveTrusted" style="margin-top:10px">${nx('save')}</button></section><section class="card"><h2>${nx('anti_scam')}</h2><p class="muted">${nx('anti_scam_copy')}</p><div class="trust-stack"><div class="trust-row"><div class="trust-icon">!</div><div><b>${nx('report_fast')}</b><span>${nx('report_fast_copy')}</span></div></div><div class="trust-row"><div class="trust-icon">◉</div><div><b>${nx('no_number')}</b><span>${nx('no_number_copy')}</span></div></div></div></section></div>`)
}


function languageBar(){return `<div class="langbar" role="group" aria-label="${esc(tr('app_language'))}">${LANGS.map(([code,label])=>`<button type="button" data-lang="${code}" aria-pressed="${state.settings.language===code}">${label}</button>`).join('')}</div>`}
function utilityBar(){return `${api.live?'':`<div class="demo-banner" role="status">${ax('demo_banner')}</div>`}<div class="utilitybar"><div class="utility-inner"><div class="utility-trust"><span><b>✓</b>${tr('secure_note')}</span></div>${languageBar()}</div></div>`}
function topShell(content){const nav=[['home','home'],['discover','discover'],['matches','matches'],['marriage','marriage'],['profile','profile']];return `<div class="shell">${utilityBar()}<header class="topbar"><div class="topbar-inner"><div class="brand"><div class="brand-mark">♡</div>Nikah.App</div><nav class="nav">${nav.map(([r,k])=>`<button data-route="${r}" class="${state.route===r?'active':''}">${tr(k)}</button>`).join('')}</nav><div class="nav-tools"><button class="account-btn shield-btn" data-route="safety" aria-label="${nx('trust_nav')}">🛡 <span>${nx('trust_nav')}</span></button><button class="account-btn" data-route="settings"><span class="account-dot"></span><span>${tr('settings')}</span></button></div></div></header><main class="container">${content}</main><nav class="bottomnav">${nav.map(([r,k])=>`<button data-route="${r}" class="${state.route===r?'active':''}">${tr(k)}</button>`).join('')}</nav></div>`}

function authView(){const mode=state.auth.mode;let body='';
 if(mode==='register')body=`<div class="eyebrow">${tr('serious')}</div><h1>${tr('create_account')}</h1><p class="muted">${tr('register_copy')}</p><form id="registerForm" class="form"><div class="field"><label>${tr('email')}</label><input required type="email" name="email" autocomplete="email" placeholder="name@example.com"></div><div class="field"><label>${tr('phone')}</label><input required name="phone" autocomplete="tel" placeholder="+90 5xx xxx xx xx"></div><div class="field"><label>${tr('password')}</label><input required minlength="8" type="password" name="password" autocomplete="new-password" placeholder="${tr('password_hint')}"></div><label class="checkline"><input required type="checkbox" name="age">${tr('age_confirm')}</label><button class="btn">${tr('register_verify')}</button></form><div class="field-inline" style="margin-top:10px"><button class="btn ghost small" data-auth="login">${tr('have_account')}</button><button class="btn ghost small" data-auth="forgot">${tr('forgot')}</button></div>`;
 if(mode==='login')body=`<h1>${tr('sign_in')}</h1><p class="muted">${tr('sign_in_copy')}</p><form id="loginForm" class="form"><div class="field"><label>${tr('email_phone')}</label><input required name="id" autocomplete="username"></div><div class="field"><label>${tr('password')}</label><input required type="password" name="password" autocomplete="current-password"></div><button class="btn">${tr('sign_in')}</button></form><div class="field-inline" style="margin-top:10px"><button class="btn ghost small" data-auth="register">${tr('new_account')}</button><button class="btn ghost small" data-auth="forgot">${tr('forgot')}</button></div>`;
 if(mode==='forgot')body=`<h1>${tr('reset_password')}</h1><p class="muted">${tr('reset_copy')}</p><form id="forgotForm" class="form"><div class="field"><label>${tr('email_phone')}</label><input required name="id"></div><button class="btn">${tr('send_reset')}</button></form><button class="btn ghost small" data-auth="login" style="margin-top:10px">${tr('back_signin')}</button>`;
 if(mode==='otp')body=`<h1>${tr('phone_verify')}</h1><p class="muted">${tr('code_sent')} <strong>${esc(state.auth.pending?.phone||state.user.phone)}</strong>. ${api.live?`<span class="muted">${ax('check_inbox')}</span>`:`<span class="badge warn">${tr('demo_code')}</span>`}</p><form id="otpForm" class="form"><div class="field"><label>${tr('verification_code')}</label><input required inputmode="numeric" maxlength="6" name="otp" placeholder="123456"></div><button class="btn">${tr('verify')}</button></form><div class="field-inline" style="margin-top:10px"><button class="btn secondary small" id="resendOtp">${tr('resend')}</button><button class="btn ghost small" data-auth="register">${tr('change_number')}</button></div>`;
 return `<div class="shell">${utilityBar()}<div class="auth-shell"><section class="auth-visual"><div><div class="brand auth-brand"><div class="brand-mark">♡</div>Nikah.App</div><div class="eyebrow" style="color:#ffd5e3">${tr('serious')}</div><h2 class="auth-title">${tr('auth_title')}</h2><p class="auth-copy">${tr('auth_copy')}</p>${stats?statsCard(true):''}<div class="auth-points"><div class="auth-point"><b>${tr('trust_age')}</b><span>${tr('trust_age_copy')}</span></div><div class="auth-point"><b>${tr('trust_verify')}</b><span>${tr('trust_verify_copy')}</span></div><div class="auth-point"><b>${tr('trust_privacy')}</b><span>${tr('trust_privacy_copy')}</span></div></div></div><span style="font-size:12px;color:rgba(255,255,255,.62)">Nikah.App • Global Marriage Platform</span></section><section class="auth-panel"><div class="auth-card">${body}<p class="legal">${tr('legal')}</p>${legalLinks()}</div></section></div></div>`}

function onboardingView(){const s=state.user.onboardingStep||1,pct=Math.round((s-1)/6*100);const labels=['basic_info','looking_for','marriage_intent','profile_bio','photo_verify','confirmations'];let body='';
 if(s===1)body=`<form id="onboardForm" class="form" data-step="1"><div class="grid two"><div class="field"><label>${tr('first_name')}</label><input required name="firstName" value="${esc(state.user.firstName)}"></div><div class="field"><label>${tr('last_name')}</label><input required name="lastName" value="${esc(state.user.lastName)}"></div><div class="field"><label>${tr('dob')}</label><input required type="date" name="dob" value="${esc(state.user.dob)}"></div><div class="field"><label>${tr('gender')}</label><select required name="gender"><option value="">${tr('select')}</option>${['Kadın','Erkek','Diğer'].map(x=>`<option value="${x}" ${state.user.gender===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="field"><label>${tr('country')}</label><select name="country">${['Türkiye','Endonezya','Malezya','Almanya','Fransa','Hollanda','Diğer'].map(x=>`<option value="${x}" ${state.user.country===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="field"><label>${tr('city')}</label><input required name="city" value="${esc(state.user.city)}"></div></div><button class="btn">${tr('continue')}</button></form>`;
 if(s===2)body=`<form id="onboardForm" class="form" data-step="2"><div class="field"><label>${tr('who_looking')}</label><select required name="seeking"><option value="">${tr('select')}</option>${['Kadın','Erkek','Fark etmez'].map(x=>`<option ${state.user.seeking===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="grid two"><div class="field"><label>${tr('min_age')}</label><input type="number" min="18" max="80" name="minAge" value="${state.preferences.minAge}"></div><div class="field"><label>${tr('max_age')}</label><input type="number" min="18" max="80" name="maxAge" value="${state.preferences.maxAge}"></div></div><div class="field"><label>${tr('discovery_area')}</label><select name="distance">${['Global','Ülkem','Şehrim'].map(x=>`<option value="${x}" ${state.preferences.distance===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><button class="btn">${tr('continue')}</button></form>`;
 if(s===3)body=`<form id="onboardForm" class="form" data-step="3"><div class="field"><label>${tr('your_intent')}</label><select name="intent">${['Evliliğe hazırım','Sadece tanışıyorum','Evlilik sürecinde danışmanlık istiyorum'].map(x=>`<option value="${x}" ${state.user.intent===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="grid two"><div class="field"><label>${tr('children_plan')}</label><select name="children">${['İstiyorum','İstemiyorum','Kararsız'].map(x=>`<option value="${x}" ${state.user.children===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="field"><label>${tr('family_role')}</label><select name="family">${['Çok önemli','Önemli','Daha bağımsız'].map(x=>`<option value="${x}" ${state.user.family===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div></div><div class="field"><label>${tr('relocation')}</label><select name="relocation">${['Uygun','Kararsız','Uygun değil'].map(x=>`<option value="${x}" ${state.user.relocation===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="compat-quiz"><div><b>${nx('compat_profile')}</b><p>${nx('compat_profile_copy')}</p></div><div class="grid two"><div class="field"><label>${nx('communication_style')}</label><select name="compatCommunication"><option value="direct" ${state.user.compat?.communication==='direct'?'selected':''}>${nx('direct')}</option><option value="gentle" ${state.user.compat?.communication==='gentle'?'selected':''}>${nx('gentle')}</option></select></div><div class="field"><label>${nx('planning_style')}</label><select name="compatPlanning"><option value="planned" ${state.user.compat?.planning==='planned'?'selected':''}>${nx('planned')}</option><option value="flexible" ${state.user.compat?.planning==='flexible'?'selected':''}>${nx('flexible')}</option></select></div><div class="field"><label>${nx('social_energy')}</label><select name="compatSocial"><option value="balanced" ${state.user.compat?.social==='balanced'?'selected':''}>${nx('social_balanced')}</option><option value="home" ${state.user.compat?.social==='home'?'selected':''}>${nx('social_home')}</option></select></div><div class="field"><label>${nx('conflict_style')}</label><select name="compatConflict"><option value="calm" ${state.user.compat?.conflict==='calm'?'selected':''}>${nx('calm')}</option><option value="space" ${state.user.compat?.conflict==='space'?'selected':''}>${nx('space')}</option></select></div><div class="field"><label>${nx('money_style')}</label><select name="compatMoney"><option value="planned" ${state.user.compat?.money==='planned'?'selected':''}>${nx('money_planned')}</option><option value="flexible" ${state.user.compat?.money==='flexible'?'selected':''}>${nx('money_flexible')}</option></select></div></div></div><button class="btn">${tr('continue')}</button></form>`;
 if(s===4)body=`<form id="onboardForm" class="form" data-step="4"><div class="grid two"><div class="field"><label>${tr('occupation')}</label><input name="job" value="${esc(state.user.job)}"></div><div class="field"><label>${tr('education')}</label><input name="education" value="${esc(state.user.education)}"></div></div><div class="field"><label>${tr('tell_about')}</label><textarea required maxlength="500" rows="6" name="about" placeholder="${tr('about_hint')}">${esc(state.user.about)}</textarea></div><button class="btn">${tr('continue')}</button></form>`;
 if(s===5)body=`<form id="onboardForm" class="form" data-step="5"><div class="photo-drop">${state.user.photo?`<img alt="Profile" src="${state.user.photo}">`:`<div><div class="portrait-orb" style="width:110px;height:110px;font-size:34px;margin:0 auto 18px">${initials(state.user.firstName||'N')}</div><strong>${tr('add_photo')}</strong><p class="muted">${tr('photo_hint')}</p><input id="photoInput" type="file" accept="image/*"></div>`}</div>${state.user.photo?`<button type="button" class="btn secondary" id="changePhoto">${tr('change_photo')}</button>`:''}${verificationBlock()}<button class="btn">${tr('continue')}</button></form>`;
 if(s===6)body=`<form id="onboardForm" class="form" data-step="6"><p class="muted">${ax('legal_links_hint')}</p>${legalLinks()}<label class="checkline"><input required type="checkbox" name="terms" ${state.user.terms?'checked':''}>${tr('terms_accept')} <button type="button" class="linklike" data-route="legal:terms">↗</button></label><label class="checkline"><input required type="checkbox" name="privacy" ${state.user.privacy?'checked':''}>${tr('privacy_accept')} <button type="button" class="linklike" data-route="legal:privacy">↗</button></label><label class="checkline"><input required type="checkbox" name="consent" ${state.user.consent?'checked':''}>${legalDoc('consent',state.settings.language).title} <button type="button" class="linklike" data-route="legal:consent">↗</button></label><label class="checkline"><input required type="checkbox" name="ageConfirmed" ${state.user.ageConfirmed?'checked':''}>${tr('age_reconfirm')}</label><button class="btn">${tr('finish_profile')}</button></form>`;
 const content=`<div class="onboarding-wrap"><aside class="onboarding-side card flat"><div class="brand"><div class="brand-mark">♡</div>Nikah.App</div><p class="muted" style="margin-bottom:10px">${tr('profile_setup')}</p><div class="progress"><div style="width:${pct}%"></div></div><div class="steps">${labels.map((k,i)=>`<div class="step ${s===i+1?'active':''} ${s>i+1?'done':''}">${i+1}. ${tr(k)}</div>`).join('')}</div></aside><section class="card onboarding-card"><div class="eyebrow">${tr('step')} ${s}/6</div><h1>${tr(labels[s-1])}</h1><p class="muted">${s===1?tr('register_copy'):s===3?tr('compatibility_copy'):tr('profile_setup')}</p>${body}${s>1?`<button class="btn ghost small" id="onboardBack" style="margin-top:10px">← ${tr('back')}</button>`:''}</section></div>`;return topShell(content)}

function homeView(){const suggested=profiles.filter(eligibleProfile).sort((a,b)=>kindRank(a)-kindRank(b)||compatScore(b)-compatScore(a))[0];return topShell(`<section class="home-hero"><div class="card home-main"><div class="eyebrow">${tr('home_eyebrow')}</div><h1>${tr('home_title')}</h1><p>${tr('home_copy')}</p><div class="field-inline" style="margin-top:22px;flex-wrap:wrap"><button class="btn" data-route="discover">${tr('discover_people')}</button><button class="btn secondary" data-route="marriage">${tr('my_marriage_path')}</button><button class="btn ghost" data-route="safety">🛡 ${nx('trust_nav')}</button></div></div><aside class="card"><h2>${tr('trust_center')}</h2><div class="trust-stack"><div class="trust-row"><div class="trust-icon">✓</div><div><b>${tr('verified_community')}</b><span>${tr('verified_community_copy')}</span></div></div><div class="trust-row"><div class="trust-icon">◉</div><div><b>${tr('private_design')}</b><span>${tr('private_design_copy')}</span></div></div><div class="trust-row"><div class="trust-icon">文</div><div><b>${tr('multilingual_chat')}</b><span>${tr('multilingual_chat_copy')}</span></div></div></div></aside></section><section class="grid four" style="margin-top:18px"><div class="card metric-card"><div class="metric-number">${profilePct()}%</div><div class="metric-label">${tr('profile_readiness')}</div></div><div class="card metric-card"><div class="metric-number">${state.matches.length}</div><div class="metric-label">${tr('match_count')}</div></div><div class="card metric-card"><div class="metric-number">${state.marriage.stage}/6</div><div class="metric-label">${tr('marriage_progress')}</div></div><div class="card metric-card"><div class="metric-number">${suggested?compatScore(suggested)+'%':'—'}</div><div class="metric-label">${nx('daily_quality')}${suggested?' • '+esc(suggested.name):''}</div></div></section>${stats?`<section style="margin-top:18px">${statsCard()}</section>`:''}`)}

function factorRow(label,pct){return `<div class="factor"><div class="factor-head"><span>${label}</span><span>${pct}%</span></div><div class="bar"><div style="width:${pct}%"></div></div></div>`}
function filtersPanel(){return `<aside class="filter-panel card"><h3>${tr('filters')}</h3><div class="filter-group"><div class="filter-label"><span>${tr('filter_age')}</span><b>${state.preferences.minAge}–${state.preferences.maxAge}</b></div><div class="dealbreaker"><span>${tr('dealbreaker')}</span><span class="switch ${state.preferences.dealbreakers?.age?'on':''}" data-dealbreaker="age"></span></div></div><div class="filter-group"><div class="filter-label"><span>${tr('region')}</span><b>${tv(state.preferences.distance)}</b></div><div class="dealbreaker"><span>${tr('dealbreaker')}</span><span class="switch ${state.preferences.dealbreakers?.region?'on':''}" data-dealbreaker="region"></span></div></div><div class="filter-group"><div class="filter-label"><span>${tr('intention')}</span><b>${tv(state.preferences.intent)}</b></div><div class="dealbreaker"><span>${tr('dealbreaker')}</span><span class="switch ${state.preferences.dealbreakers?.intent?'on':''}" data-dealbreaker="intent"></span></div></div><div class="filter-group"><div class="filter-label"><span>${tr('verified_only')}</span><b>${state.preferences.verifiedOnly?'✓':'—'}</b></div><div class="dealbreaker"><span>${tr('verified_only')}</span><span class="switch ${state.preferences.verifiedOnly?'on':''}" data-verified-toggle></span></div></div><button class="btn secondary small" data-route="profile" style="width:100%;margin-top:14px">${tr('edit_filters')}</button></aside>`}
function profilePortrait(p){const blur=p.photoBlur&&!state.matches.includes(p.id);return `<div class="profile-visual">${p.photo?`<img class="portrait-photo${blur?' blurred':''}" src="${esc(p.photo)}" alt="">${blur?`<div class="photo-lock">🔒 ${ax('photo_private')}</div>`:''}`:`<div class="abstract-person"><div class="portrait-ring"></div><div class="portrait-orb">${initials(p.name)}</div></div>`}<div class="visual-gradient"></div><div class="visual-top">${p.kind==='showcase'||p.kind==='team'?kindBadge(p):`<span class="badge ok">● ${p.verified?tr('verified'):tr('verification_pending')}</span>`}<div class="score-pill"><div class="score-ring" style="--score:${compatScore(p)}%"><b>${compatScore(p)}</b></div><span>${tr('compatibility')}</span></div></div><div class="visual-bottom"><div class="profile-name"><h2>${esc(p.name)}, ${p.age}</h2>${p.verified?'<span class="verified-mark">✓</span>':''}</div><div class="profile-meta"><span>${esc(p.city)}, ${tv(p.country)}</span><span>•</span><span>${tv(p.job)}</span></div></div></div>`}
function profileCard(p){const lang=state.settings.language;const showTranslated=state.translatedProfiles?.[p.id];const bio=showTranslated?(p.bio[lang]||p.bio[homeLang(p)]||p.bio.en||''):(p.bio[homeLang(p)]||p.bio.en||Object.values(p.bio||{})[0]||'');return `<article class="card profile-card">${profilePortrait(p)}<div class="profile-body"><div class="profile-section"><div class="chips"><span class="chip">♡ ${tv(p.intent)}</span><span class="chip">${tr('children')}: ${tv(p.children)}</span><span class="chip">${tr('family')}: ${tv(p.family)}</span><span class="chip">↗ ${tv(p.relocation)}</span>${(p.languages||[]).map(x=>`<span class="chip">文 ${esc(x)}</span>`).join('')}</div></div>${p.kind==='showcase'?`<div class="showcase-note">${ax('showcase_note')}</div>`:p.kind==='team'?`<div class="team-note">${ax('team_note')}</div>`:''}<div class="profile-section"><h4>${tr('about')}</h4><p class="bio">${esc(bio)}</p>${lang!==(homeLang(p))?`<button class="btn ghost small" data-translate-profile="${p.id}" style="padding-left:0">${showTranslated?tr('hide_translation'):tr('show_translation')}</button>`:''}</div><div class="profile-section"><h4>${tr('prompts')}</h4>${(p.prompts||[]).map(([k,vals])=>`<div class="prompt-card"><span>${tr(k)}</span><strong>${esc((showTranslated?(vals[lang]||vals[homeLang(p)]||vals.en):(vals[homeLang(p)]||vals.en||Object.values(vals||{})[0]))||'')}</strong></div>`).join('')}</div></div><div class="profile-actions"><button class="action-pass" data-pass="${p.id}" aria-label="${tr('pass')}">×</button>${p.kind==='showcase'?'':`<button class="action-super" data-super="${p.id}">★ ${tr('super')}</button>`}<button class="action-like" data-like="${p.id}">${state.liked.includes(p.id)?'✓ '+tr('liked'):'♥ '+tr('like')}</button>${p.kind==='showcase'?'':`<button class="action-more" data-more="${p.id}" aria-label="${tr('more')}">•••</button>`}</div></article>`}
function compatPanel(p){const c=compatibilityData(p);return `<aside class="compat-panel"><div class="card"><div class="compat-score"><div class="compat-big">${c.score}%</div><div><b>${nx('compat_live')}</b><p>${tr('compatibility_copy')}</p></div></div>${factorRow(tr('values'),c.factors[0])}${factorRow(tr('family'),c.factors[1])}${factorRow(tr('lifestyle'),c.factors[2])}${factorRow(tr('communication'),c.factors[3])}<div class="reason-list">${c.reasons.map(r=>`<div class="reason"><i>✓</i><span>${tr(r)}</span></div>`).join('')}</div></div><div class="card"><h3>${tr('trust_signals')}</h3><div class="trust-meter"><strong>${trustScore(p)}</strong><span>/100 • ${nx('trust_level')}</span></div><div class="trust-mini"><div><b>✓</b>${tr('phone')}</div><div><b>${p.verified?'✓':'—'}</b>${tr('selfie')}</div><div><b>✓</b>${tr('profile_complete')}</div></div></div></aside>`}
function discoverView(){const p=profiles.filter(eligibleProfile).sort((a,b)=>kindRank(a)-kindRank(b)||compatScore(b)-compatScore(a))[0];if(!p)return topShell(`<div class="card empty"><h2>${tr('no_profiles')}</h2>${api.live?'':`<button class="btn" id="resetPasses">${tr('reset_profiles')}</button>`}</div>`);return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('discover_eyebrow')}</div><h1>${tr('discover_title')}</h1><p>${tr('discover_copy')}</p></div><button class="btn secondary mobile-filter-btn" id="mobileFilter">${tr('filters')}</button></div><div class="discover-layout" id="discoverLayout">${filtersPanel()}${profileCard(p)}${compatPanel(p)}</div>`)}

function matchesView(){const list=matchProfiles.filter(p=>!state.blocked.includes(p.id));if(!list.length)return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('matches')}</div><h1>${tr('matches_title')}</h1><p>${tr('matches_copy')}</p></div></div><div class="card empty"><h2>${tr('no_matches')}</h2><p>${tr('no_matches_copy')}</p><button class="btn" data-route="discover">${tr('start_discovering')}</button></div>`);return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('matches')}</div><h1>${tr('matches_title')}</h1><p>${tr('matches_copy')}</p></div></div><div class="grid two"><section class="card"><div class="match-list">${list.map(p=>`<div class="match-item"><div class="avatar">${p.photo?`<img src="${esc(p.photo)}" alt="">`:initials(p.name)}</div><div class="grow"><strong>${esc(p.name)}, ${p.age} ${p.kind==='team'?kindBadge(p):''}</strong><div class="muted">${esc(p.city)} • ${compatScore(p)}% ${tr('compatibility')}</div></div><button class="btn small" data-chat="${p.id}">${tr('message')}</button></div>`).join('')}</div></section><section class="card"><h2>${tr('relationship_forward')}</h2><p class="muted">${tr('marriage_copy')}</p><button class="btn" data-route="marriage">${tr('marriage_path_open')}</button></section></div>`)}

function chatView(id){const p=findProfile(id);if(!p)return matchesView();if(state.settings.verifiedChatsOnly&&!p.verified)return topShell(`<div class="card verified-gate"><div class="trust-icon big">🛡</div><h2>${nx('trust_gate')}</h2><p class="muted">${nx('trust_gate_copy')}</p><div class="field-inline"><button class="btn" data-request-verify="${p.id}">${nx('request_verify')}</button><button class="btn secondary" data-route="matches">${tr('back')}</button></div></div>`);const msgs=state.messages[chatKey(p)]||[];const starters=conversationStarters(p);const lang=state.settings.language;return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('matches')}</div><h1>${esc(p.name)}</h1></div></div><div class="card chat"><div class="chat-head"><div class="field-inline"><div class="avatar">${p.photo?`<img src="${esc(p.photo)}" alt="">`:initials(p.name)}</div><div><b>${esc(p.name)}</b> ${p.kind==='team'?kindBadge(p):''}<div class="muted">${p.verified?'✓ '+tr('verified_profile'):tr('verification_pending')}</div></div></div><div class="field-inline"><button class="btn small secondary" data-call="voice:${p.id}">◉ ${nx('voice_call')}</button><button class="btn small secondary" data-call="video:${p.id}">▣ ${nx('video_call')}</button><button class="btn small secondary" id="translateToggle">${state.settings.translation?tr('translation_on'):tr('translation_off')}</button><button class="btn small ghost" data-more="${p.id}">•••</button></div></div><div class="messages">${!msgs.length?`<div class="convo-starters"><b>${nx('starter_title')}</b><p>${nx('starter_copy')}</p>${starters.map((x,i)=>`<button class="starter" data-chat-starter="${i}">${esc(x)}</button>`).join('')}</div>`:''}${msgs.map((m,i)=>{const tx=m.tx||(m.translations&&m.translations[lang]);const showTx=state.settings.translation&&m.from==='them'&&tx;return `<div class="bubble ${m.from==='me'?'me':''}">${esc(showTx?tx:m.text)}${showTx?`<small>${tr('auto_translation')}</small>`:''}${!showTx&&m.from==='them'&&state.settings.translation&&api.live?`<button type="button" class="bubble-translate" data-translate-msg="${i}">${tr('show_translation')}</button>`:''}</div>`}).join('')}</div><form id="chatForm" class="chat-input" data-id="${p.id}"><input required name="message" maxlength="1000" placeholder="${tr('write_message')}"><button class="btn">${tr('send')}</button></form></div>`)}

const DOC_TYPES=[['passport','passport'],['birth','birth_certificate'],['single','single_certificate'],['apostille','apostille'],['translation','certified_translation'],['kua','application_docs']];
const marriageSteps=[['serious_decision','serious_decision_copy'],['family_meeting','family_meeting_copy'],['docs_plan','docs_plan_copy'],['apostille_translation','apostille_translation_copy'],['official_application','official_application_copy'],['after_marriage','after_marriage_copy']];
function advisoryPanel(){
 const pk=state.advisory.packages||DEMO_PACKAGES,sel=state.advisory.selectedPackage,reqs=state.advisory.requests||[],cfg=window.NIKAH_CONFIG||{};
 const pkgName=code=>{const k=(pk.find(x=>x.code===code)||{}).nameKey||code;return k==='vip'?'VIP':tr(k)};
 const disc=state.user.founder?(stats?.founder_discount_pct||0):0;const priceHtml=p=>disc?`<span class="price-old">${money(p.priceCents,p.currency)}</span> ${money(Math.round(p.priceCents*(100-disc)/100),p.currency)}`:money(p.priceCents,p.currency);
 return `<div class="card advisory"><h3>${ax('adv_title')}</h3><p class="muted">${ax('adv_lead')}</p>
${disc?`<div class="callout"><b>★ ${ax('founder_badge')}</b><p>${ax('founder_discount',{pct:pct(disc)})}</p></div>`:''}<div class="pkg-grid">${pk.map(p=>`<div class="pkg ${sel===p.code?'selected':''}"><div class="pkg-head"><b>${pkgName(p.code)}</b><span class="pkg-price">${priceHtml(p)}</span></div><ul>${(p.features||[]).map(f=>`<li>${ax(f)}</li>`).join('')}</ul><button type="button" class="btn small ${sel===p.code?'':'secondary'}" data-pkg="${p.code}">${sel===p.code?'✓ '+ax('adv_selected'):ax('adv_select')}</button></div>`).join('')}</div>
<form id="advisoryForm" class="form" style="margin-top:14px"><h4>${ax('adv_form_title')}</h4><div class="grid two"><div class="field"><label>${ax('adv_contact_email')}</label><input type="email" name="contactEmail" value="${esc(state.user.email)}"></div><div class="field"><label>${ax('adv_contact_phone')}</label><input name="contactPhone" value="${esc(state.user.phone)}"></div></div><div class="grid two"><div class="field"><label>${ax('adv_whatsapp')}</label><input name="whatsapp" placeholder="+90…"></div><div class="field"><label>${ax('adv_country_from')}</label><input name="countryFrom" value="${esc(tv(state.user.country))}"></div></div><div class="field"><label>${ax('adv_country_to')}</label><input name="countryTo"></div><div class="field"><label>${ax('adv_notes')}</label><textarea name="notes" rows="3" maxlength="2000"></textarea></div><button class="btn">${ax('adv_submit')}</button><p class="muted" style="margin-top:8px">${api.live?ax('adv_pay_hint'):ax('adv_demo_payment')}</p>${cfg.advisorWhatsApp?`<p class="muted">WhatsApp: ${esc(cfg.advisorWhatsApp)}</p>`:''}${cfg.advisorEmail?`<p class="muted">${esc(cfg.advisorEmail)}</p>`:''}</form>
<h4 style="margin-top:18px">${ax('adv_my_requests')}</h4>${!reqs.length?`<p class="muted">${ax('adv_none')}</p>`:reqs.map(r=>`<div class="adv-req"><div class="adv-req-head"><b>${pkgName(r.packageCode)}</b><span>${r.discountPct?`<span class="price-old">${money(r.listPriceCents,r.currency)}</span> `:''}${money(r.priceCents,r.currency)}</span></div><span class="badge ${['paid','completed','in_progress'].includes(r.status)?'ok':r.status==='cancelled'?'':'warn'}">${ax('adv_status_'+r.status)}</span><div class="muted" style="margin-top:6px">${new Date(r.createdAt).toLocaleDateString()}</div>${(r.documents||[]).length?`<div class="muted">${r.documents.length} ${ax('adv_uploaded')}: ${r.documents.map(d=>esc(d.name||d.docType)).join(', ')}</div>`:''}<div class="field-inline" style="margin-top:8px">${r.status==='awaiting_payment'?`<button type="button" class="btn small" data-pay="${r.id}">${ax('adv_pay')}</button><button type="button" class="btn small ghost" data-cancel-req="${r.id}">${ax('adv_cancel')}</button>`:''}</div>${['awaiting_payment','paid','in_progress'].includes(r.status)?`<div class="field-inline" style="margin-top:8px"><select data-doc-type="${r.id}" aria-label="${ax('adv_doc_type')}">${DOC_TYPES.map(([k,l])=>`<option value="${k}">${tr(l)}</option>`).join('')}<option value="other">${ax('adv_other')}</option></select><label class="btn small secondary">${ax('adv_upload')}<input type="file" accept="image/*,application/pdf" data-upload="${r.id}" hidden></label></div>`:''}</div>`).join('')}<p class="muted" style="margin-top:8px">${ax('adv_docs_private')}</p></div>`;
}
function marriageView(){const d=state.marriage.documents,checked=Object.values(d).filter(Boolean).length,stage=state.marriage.stage;return topShell(`<div class="card marriage-hero"><div class="eyebrow" style="color:#ffd7e5">${tr('from_match_marriage')}</div><h2>${tr('roadmap')}</h2><p>${tr('marriage_copy')}</p></div><div class="grid two" style="margin-top:18px"><section class="card"><h2>${tr('roadmap')}</h2><div class="timeline">${marriageSteps.map(([title,copy],i)=>`<div class="timeline-item ${stage>i?'done':''}"><div class="timeline-num">${stage>i?'✓':i+1}</div><div class="timeline-content"><b>${tr(title)}</b><p>${tr(copy)}</p>${stage===i?`<button class="btn small" data-stage-next="${i+1}" style="margin-top:9px">${tr('complete_step')}</button>`:''}</div></div>`).join('')}</div></section><aside class="grid"><div class="card"><h3>${tr('docs_checklist')}</h3>${DOC_TYPES.map(([k,l])=>`<label class="checkline" style="margin:11px 0"><input type="checkbox" data-doc="${k}" ${d[k]?'checked':''}>${tr(l)}</label>`).join('')}<p class="muted">${checked}/6 ${tr('complete')}</p></div>${advisoryPanel()}</aside></div>`)}

function profileView(){return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('profile')}</div><h1>${tr('my_profile')}</h1></div></div><div class="grid two"><section class="card"><div class="profile-summary"><div class="avatar">${state.user.photo?`<img src="${state.user.photo}" alt="">`:initials(state.user.firstName||'N')}</div><div><h2>${esc(state.user.firstName)} ${esc(state.user.lastName)}</h2>${state.user.founder?`<span class="badge kind-team">★ ${ax('founder_badge')}${state.user.founderNo?' #'+state.user.founderNo:''}</span>`:''}<div class="muted">${esc(state.user.city)}, ${tv(state.user.country)} • ${calcAge(state.user.dob)||'—'} ${tr('years')}</div></div></div><div class="kpi"><span>${tr('completion')}</span><strong>${profilePct()}%</strong></div><div class="kpi"><span>${tr('intention')}</span><strong>${tv(state.user.intent)}</strong></div><div class="kpi"><span>${tr('phone')}</span><strong>${state.user.phoneVerified?'✓ '+tr('verified'):'—'}</strong></div><div class="kpi"><span>${tr('selfie')} / ID</span><strong>${state.user.selfieVerified?'✓':'—'} / ${state.user.identityVerified?'✓':'—'}</strong></div>${verificationBlock()}<button class="btn secondary" id="restartOnboarding" style="margin-top:14px">${tr('edit_profile')}</button></section><section class="card"><h2>${tr('preferences')}</h2><form id="prefsForm" class="form"><div class="grid two"><div class="field"><label>${tr('min_age')}</label><input name="minAge" type="number" min="18" max="80" value="${state.preferences.minAge}"></div><div class="field"><label>${tr('max_age')}</label><input name="maxAge" type="number" min="18" max="80" value="${state.preferences.maxAge}"></div></div><div class="field"><label>${tr('discovery_area')}</label><select name="distance">${['Global','Ülkem','Şehrim'].map(x=>`<option value="${x}" ${state.preferences.distance===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><div class="field"><label>${tr('intention')}</label><select name="intent">${['Evliliğe hazırım','Sadece tanışıyorum','Fark etmez'].map(x=>`<option value="${x}" ${state.preferences.intent===x?'selected':''}>${tv(x)}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" name="verifiedOnly" ${state.preferences.verifiedOnly?'checked':''}>${tr('verified_only')}</label><button class="btn">${tr('save_preferences')}</button></form></section></div>`)}

function settingsView(){return topShell(`<div class="page-head"><div><div class="eyebrow">${tr('settings')}</div><h1>${tr('settings')}</h1></div></div><div class="grid two"><section class="card"><h2>${tr('app_language')}</h2><div class="settings-section"><div class="setting-row"><div><b>${tr('translation_messages')}</b></div><span class="switch ${state.settings.translation?'on':''}" data-setting-toggle="translation" role="switch" aria-checked="${state.settings.translation}"></span></div><div class="setting-row"><div><b>${tr('discoverable')}</b></div><span class="switch ${state.settings.discoverable?'on':''}" data-setting-toggle="discoverable" role="switch" aria-checked="${state.settings.discoverable}"></span></div><div class="setting-row"><div><b>${tr('notifications')}</b></div><span class="switch ${state.settings.notifications?'on':''}" data-setting-toggle="notifications" role="switch" aria-checked="${state.settings.notifications}"></span></div><div class="setting-row"><div><b>${nx('quality_mode')}</b><span>${nx('quality_mode_copy')}</span></div><span class="switch ${state.settings.qualityMode?'on':''}" data-setting-toggle="qualityMode" role="switch" aria-checked="${state.settings.qualityMode}"></span></div><div class="setting-row"><div><b>${nx('verified_chat')}</b><span>${nx('verified_chat_copy')}</span></div><span class="switch ${state.settings.verifiedChatsOnly?'on':''}" data-setting-toggle="verifiedChatsOnly" role="switch" aria-checked="${state.settings.verifiedChatsOnly}"></span></div></div><div style="margin-top:16px">${languageBar()}</div></section><section class="card"><h2>${tr('privacy_account')}</h2><p class="muted">${tr('privacy_copy')}</p><div class="kpi"><span>${tr('blocked_profiles')}</span><strong>${state.blocked.length}</strong></div><div class="kpi"><span>${tr('reports')}</span><strong>${state.reports.length}</strong></div><button class="btn secondary" data-route="safety" style="margin-top:14px">🛡 ${nx('trust_title')}</button>${legalLinks()}<div class="field-inline" style="margin-top:16px"><button class="btn secondary" id="logout">${tr('signout')}</button><button class="btn danger" id="deleteAccount">${tr('delete_account')}</button></div></section></div>`)}

function legalLinks(){return `<nav class="legal-links">${LEGAL_DOCS.map(d=>`<button type="button" data-route="legal:${d}">${legalDoc(d,state.settings.language).title}</button>`).join('')}</nav>`}
function legalView(docSpec){const forceTr=/\.tr$/.test(docSpec);const doc=docSpec.replace(/\.tr$/,'');const {title,body}=legalDoc(doc,forceTr?'tr':state.settings.language);
 const inner=`<div class="page-head"><div><div class="eyebrow">${ax('legal_nav')}</div><h1>${esc(title)}</h1></div><button class="btn secondary small" data-route="${state.session?'settings':'home'}">${tr('back')}</button></div><article class="card legal-doc">${body}</article>${legalLinks()}`;
 return state.session&&state.user.profileComplete?topShell(inner):`<div class="shell">${utilityBar()}<main class="container">${inner}</main></div>`}
function modal(html){const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;d.addEventListener('click',e=>{if(e.target===d||e.target.matches('[data-close]'))d.remove()});document.body.appendChild(d);return d}
function safetyModal(id){const p=findProfile(id);const m=modal(`<button class="btn ghost small" data-close>✕ ${tr('close')}</button><h2>${tr('safety')} • ${esc(p.name)}</h2><p class="muted">${tr('safety_copy')}</p><div class="field-inline">${!p.verified?`<button class="btn" data-request-verify="${id}">${nx('request_verify')}</button>`:''}<button class="btn danger" data-block-now="${id}">${tr('block')}</button><button class="btn secondary" data-report-now="${id}">${tr('report')}</button></div>`);m.addEventListener('click',e=>{if(e.target.dataset.blockNow){if(!state.blocked.includes(id))state.blocked.push(id);state.matches=state.matches.filter(x=>x!==id);matchProfiles=matchProfiles.filter(x=>x.id!==id);profiles=profiles.filter(x=>x.id!==id);save();m.remove();toast(tr('profile_blocked'));api.safety.block(id).catch(()=>{});if(state.route.startsWith('chat:'))setRoute('matches',{replace:true});else render()}if(e.target.dataset.reportNow){state.reports.push({id,reason:'user_report',at:new Date().toISOString()});save();m.remove();toast(tr('report_received'));api.safety.report(id,'user_report').catch(()=>{})}})}

function ensureChat(p){const key=chatKey(p);if(ensureChat.key!==key){if(unsubChat)unsubChat();ensureChat.key=key;unsubChat=api.messages.subscribe(key,m=>{const list=state.messages[key]=state.messages[key]||[];if(!list.some(x=>x.id&&x.id===m.id)){list.push(m);save();if(state.route==='chat:'+p.id)render()}})}
 if(api.live&&!loadedChats.has(key)){loadedChats.add(key);api.messages.list(key).then(list=>{state.messages[key]=list;save();if(state.route==='chat:'+p.id)render()}).catch(()=>{})}}
function leaveChat(){if(unsubChat){unsubChat();unsubChat=null}ensureChat.key=null}
function render(){document.documentElement.lang=state.settings.language==='zh'?'zh-CN':state.settings.language;
 if(state.ui?.loading){app.innerHTML=`<div class="shell"><div class="loading"><div class="brand"><div class="brand-mark">♡</div>Nikah.App</div><p class="muted">${ax('loading')}</p></div></div>`;return}
 if(state.route.startsWith('chat:')){const p=findProfile(state.route.split(':')[1]);if(p&&state.session)ensureChat(p)}else leaveChat();
 if(state.route.startsWith('legal:'))app.innerHTML=legalView(state.route.slice(6));else if(!state.session)app.innerHTML=authView();else if(!state.user.profileComplete)app.innerHTML=onboardingView();else if(state.route.startsWith('legal:'))app.innerHTML=legalView(state.route.slice(6));else if(state.route.startsWith('chat:'))app.innerHTML=chatView(state.route.split(':')[1]);else if(state.route==='discover')app.innerHTML=discoverView();else if(state.route==='matches')app.innerHTML=matchesView();else if(state.route==='marriage')app.innerHTML=marriageView();else if(state.route==='profile')app.innerHTML=profileView();else if(state.route==='settings')app.innerHTML=settingsView();else if(state.route==='safety')app.innerHTML=safetyView();else app.innerHTML=homeView();bind()}

function bind(){
 const fail=e=>toast((e&&e.message)||ax('error_generic'));
 $$('.switch[role="switch"]').forEach(sw=>{sw.tabIndex=0;sw.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();sw.click()}}});
 $$('[data-lang]').forEach(b=>b.onclick=()=>{state.settings.language=b.dataset.lang;save();render();syncProfile()});
 $$('[data-route]').forEach(b=>b.onclick=e=>{e.preventDefault();setRoute(b.dataset.route)});
 $$('[data-lang-doc]').forEach(a=>a.onclick=e=>{e.preventDefault();const [l,d]=a.dataset.langDoc.split(':');setRoute('legal:'+d+(l==='tr'?'.tr':''))});
 $$('[data-auth]').forEach(b=>b.onclick=()=>{state.auth.mode=b.dataset.auth;save();render()});
 const reg=$('#registerForm');if(reg)reg.onsubmit=async e=>{e.preventDefault();const f=new FormData(reg);const payload={email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),password:String(f.get('password')||'')};
  try{const r=await api.auth.register(payload);state.user.email=payload.email;state.user.phone=payload.phone;if(r.needsOtp){state.auth.mode='otp';toast(ax('otp_sent'))}else{await afterLogin()}}catch(err){fail(err)}save();render()};
 const otp=$('#otpForm');if(otp)otp.onsubmit=async e=>{e.preventDefault();const f=new FormData(otp);
  try{await api.auth.verifyOtp({code:String(f.get('otp')||'').trim()});state.user.email=state.auth.pending?.email||state.user.email;state.user.phone=state.auth.pending?.phone||state.user.phone;state.user.phoneVerified=true;state.auth.mode='login';toast(tr('phone_verified_msg'));await afterLogin()}catch(err){fail(err)}save();render()};
 const login=$('#loginForm');if(login)login.onsubmit=async e=>{e.preventDefault();const f=new FormData(login);
  try{await api.auth.login({id:String(f.get('id')||'').trim(),password:String(f.get('password')||'')});await afterLogin()}catch(err){fail(err)}save();render()};
 const forgot=$('#forgotForm');if(forgot)forgot.onsubmit=async e=>{e.preventDefault();const f=new FormData(forgot);try{await api.auth.resetPassword(String(f.get('id')||'').trim());toast(tr('reset_started'));state.auth.mode='login'}catch(err){fail(err)}save();render()};
 const resend=$('#resendOtp');if(resend)resend.onclick=()=>api.auth.resendOtp().then(()=>toast(tr('new_code'))).catch(fail);
 const back=$('#onboardBack');if(back)back.onclick=()=>{state.user.onboardingStep=Math.max(1,state.user.onboardingStep-1);save();render()};
 const onboard=$('#onboardForm');if(onboard)onboard.onsubmit=e=>{e.preventDefault();const f=new FormData(onboard),s=Number(onboard.dataset.step);if(s===1){const age=calcAge(f.get('dob'));if(age<18)return toast('18+');Object.assign(state.user,{firstName:f.get('firstName'),lastName:f.get('lastName'),dob:f.get('dob'),gender:f.get('gender'),country:f.get('country'),city:f.get('city')})}if(s===2){state.user.seeking=f.get('seeking');let min=Number(f.get('minAge')),max=Number(f.get('maxAge'));if(min>max)[min,max]=[max,min];state.preferences.minAge=min;state.preferences.maxAge=max;state.preferences.distance=f.get('distance')}if(s===3){Object.assign(state.user,{intent:f.get('intent'),children:f.get('children'),family:f.get('family'),relocation:f.get('relocation')});state.user.compat={communication:f.get('compatCommunication')||'direct',planning:f.get('compatPlanning')||'planned',social:f.get('compatSocial')||'balanced',conflict:f.get('compatConflict')||'calm',money:f.get('compatMoney')||'planned'};state.preferences.intent=f.get('intent');state.preferences.children=f.get('children')}if(s===4){Object.assign(state.user,{job:f.get('job'),education:f.get('education'),about:f.get('about')})}if(s===6){state.user.terms=!!f.get('terms');state.user.privacy=!!f.get('privacy');state.user.ageConfirmed=!!f.get('ageConfirmed');state.user.consent=!!f.get('consent');state.user.legalVersion=LEGAL_VERSION;state.user.legalAcceptedAt=new Date().toISOString();state.user.profileComplete=true;state.route='home'}if(s<6)state.user.onboardingStep=s+1;save();render();syncProfile().then(()=>{if(s===6)return refreshAll().then(render)})};
 const photo=$('#photoInput');if(photo)photo.onchange=e=>{const file=e.target.files?.[0];if(!file)return;compressProfilePhoto(file,async data=>{try{const r=await api.profile.uploadPhoto(data);state.user.photo=r.url;state.user.photoPath=r.path||'';if(!save())state.user.photo='';syncProfile()}catch(err){toast(ax('photo_upload_failed'))}render()})};
 const changePhoto=$('#changePhoto');if(changePhoto)changePhoto.onclick=()=>{state.user.photo='';state.user.photoPath='';save();render();syncProfile()};
 const sv=$('#startVerification');if(sv)sv.onclick=()=>verificationModal();
 $$('[data-like]').forEach(b=>b.onclick=()=>meaningfulLikeModal(b.dataset.like,false));
 $$('[data-super]').forEach(b=>b.onclick=()=>meaningfulLikeModal(b.dataset.super,true));
 $$('[data-pass]').forEach(b=>b.onclick=async()=>{const id=b.dataset.pass;if(!state.passed.includes(id))state.passed.push(id);save();api.discover.pass(id).catch(()=>{});if(api.live)await refreshDiscover();render()});
 $$('[data-more]').forEach(b=>b.onclick=()=>safetyModal(b.dataset.more));
 $$('[data-translate-profile]').forEach(b=>b.onclick=async()=>{const id=b.dataset.translateProfile,p=findProfile(id),lang=state.settings.language;state.translatedProfiles=state.translatedProfiles||{};
  if(!state.translatedProfiles[id]&&p&&!(p.bio||{})[lang]){if(!api.live)return toast(ax('translate_unavailable'));toast(ax('translating'));const t=await api.translate(p.bio[homeLang(p)]||'',lang);if(!t)return toast(ax('translate_unavailable'));p.bio[lang]=t;for(const [,vals] of (p.prompts||[])){if(!vals[lang]){const tt=await api.translate(vals[homeLang(p)]||'',lang);if(tt)vals[lang]=tt}}}
  state.translatedProfiles[id]=!state.translatedProfiles[id];save();render()});
 const reset=$('#resetPasses');if(reset)reset.onclick=()=>{state.passed=[];state.liked=state.liked.filter(id=>state.matches.includes(id));save();render()};
 const mobileFilter=$('#mobileFilter');if(mobileFilter)mobileFilter.onclick=()=>$('#discoverLayout')?.classList.toggle('filters-open');
 $$('[data-dealbreaker]').forEach(sw=>sw.onclick=async()=>{state.preferences.dealbreakers=state.preferences.dealbreakers||{};const k=sw.dataset.dealbreaker;state.preferences.dealbreakers[k]=!state.preferences.dealbreakers[k];save();await syncProfile();if(api.live)await refreshDiscover();render()});
 const verToggle=$('[data-verified-toggle]');if(verToggle)verToggle.onclick=async()=>{state.preferences.verifiedOnly=!state.preferences.verifiedOnly;save();await syncProfile();if(api.live)await refreshDiscover();render()};
 $$('[data-chat]').forEach(b=>b.onclick=()=>setRoute('chat:'+b.dataset.chat));
 const chat=$('#chatForm');if(chat)chat.onsubmit=async e=>{e.preventDefault();const f=new FormData(chat),id=chat.dataset.id,text=String(f.get('message')||'').trim();if(!text)return;const p=findProfile(id);if(!p)return;const key=chatKey(p);
  try{await api.messages.send(key,text);if(api.live){state.messages[key]=await api.messages.list(key)}}catch(err){return fail(err)}save();render()};
 $$('[data-translate-msg]').forEach(b=>b.onclick=async()=>{const p=findProfile(state.route.split(':')[1]);if(!p)return;const key=chatKey(p),m=(state.messages[key]||[])[Number(b.dataset.translateMsg)];if(!m)return;toast(ax('translating'));const t=await api.translate(m.text,state.settings.language);if(!t)return toast(ax('translate_unavailable'));m.tx=t;save();render()});
 const trans=$('#translateToggle');if(trans)trans.onclick=()=>{state.settings.translation=!state.settings.translation;save();render();syncProfile()};
 $$('[data-stage-next]').forEach(b=>b.onclick=()=>{state.marriage.stage=Math.max(state.marriage.stage,Number(b.dataset.stageNext));save();toast(tr('marriage_step_done'));render();api.journey.save({stage:state.marriage.stage,documents:state.marriage.documents}).catch(()=>{})});
 $$('[data-doc]').forEach(c=>c.onchange=()=>{state.marriage.documents[c.dataset.doc]=c.checked;save();render();api.journey.save({stage:state.marriage.stage,documents:state.marriage.documents}).catch(()=>{})});
 // advisory (revenue module)
 $$('[data-pkg]').forEach(b=>b.onclick=()=>{state.advisory.selectedPackage=b.dataset.pkg;save();render()});
 const advForm=$('#advisoryForm');if(advForm)advForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(advForm);const req={packageCode:state.advisory.selectedPackage,contactEmail:String(f.get('contactEmail')||'').trim(),contactPhone:String(f.get('contactPhone')||'').trim(),whatsapp:String(f.get('whatsapp')||'').trim(),countryFrom:String(f.get('countryFrom')||'').trim(),countryTo:String(f.get('countryTo')||'').trim(),notes:String(f.get('notes')||'').trim()};
  if(!req.packageCode)return toast(tr('choose_package'));if(!req.contactEmail&&!req.contactPhone)return toast(ax('adv_contact_required'));
  try{await api.advisory.create(req);await refreshAdvisory();toast(ax('adv_created'))}catch(err){return fail(err)}save();render()};
 $$('[data-pay]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api.advisory.checkout(b.dataset.pay);if(r&&r.url){location.href=r.url;return}await refreshAdvisory();toast(ax('adv_paid_ok'))}catch(err){fail(err)}save();render()});
 $$('[data-cancel-req]').forEach(b=>b.onclick=async()=>{try{await api.advisory.cancel(b.dataset.cancelReq);await refreshAdvisory();toast(ax('adv_cancelled_ok'))}catch(err){fail(err)}save();render()});
 $$('[data-upload]').forEach(inp=>inp.onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const id=inp.dataset.upload,type=$(`[data-doc-type="${id}"]`)?.value||'other';
  try{await api.advisory.uploadDocument(id,type,file);await refreshAdvisory();toast(`1 ${ax('adv_uploaded')}`)}catch(err){fail(err)}save();render()});
 const prefs=$('#prefsForm');if(prefs)prefs.onsubmit=async e=>{e.preventDefault();const f=new FormData(prefs);let min=Number(f.get('minAge')),max=Number(f.get('maxAge'));if(min>max)[min,max]=[max,min];state.preferences.minAge=min;state.preferences.maxAge=max;state.preferences.distance=f.get('distance');state.preferences.intent=f.get('intent');state.preferences.verifiedOnly=!!f.get('verifiedOnly');save();toast(tr('prefs_saved'));await syncProfile();if(api.live)await refreshDiscover();render()};
 const restart=$('#restartOnboarding');if(restart)restart.onclick=()=>{state.user.profileComplete=false;state.user.onboardingStep=1;save();render()};
 $$('[data-setting-toggle]').forEach(sw=>sw.onclick=()=>{const k=sw.dataset.settingToggle;state.settings[k]=!state.settings[k];save();render();syncProfile()});
 $$('.starter[data-chat-starter]').forEach(b=>b.onclick=()=>{const input=$('#chatForm input[name="message"]');const p=findProfile(state.route.split(':')[1]);if(input&&p)input.value=conversationStarters(p)[Number(b.dataset.chatStarter)]||''});
 $$('[data-call]').forEach(b=>b.onclick=()=>{const [kind,id]=b.dataset.call.split(':');secureCallModal(id,kind)});
 $$('[data-request-verify]').forEach(b=>b.onclick=()=>{const id=b.dataset.requestVerify;if(!state.verificationRequests.includes(id))state.verificationRequests.push(id);save();api.safety.requestVerification(id).catch(()=>{});toast(nx('verify_requested'));render()});
 const saveTrusted=$('#saveTrusted');if(saveTrusted)saveTrusted.onclick=()=>{state.safety.trustedContact=$('#trustedContact')?.value?.trim()||'';save();toast(nx('save'));syncProfile()};
 const logout=$('#logout');if(logout)logout.onclick=async()=>{try{await api.auth.logout()}catch{}state.session=false;profiles=[];matchProfiles=[];leaveChat();save();setRoute('home',{replace:true})};
 const del=$('#deleteAccount');if(del)del.onclick=()=>{const m=modal(`<h2>${tr('delete_confirm')}</h2><p class="muted">${tr('delete_copy')}</p><div class="field-inline"><button class="btn danger" id="confirmDelete">${tr('delete_permanent')}</button><button class="btn secondary" data-close>${tr('cancel')}</button></div>`);$('#confirmDelete',m).onclick=async()=>{try{await api.auth.deleteAccount()}catch(err){return fail(err)}localStorage.removeItem(STORAGE);localStorage.removeItem(LEGACY);state=structuredClone(defaults);profiles=[];matchProfiles=[];m.remove();toast(ax('account_deleted'));setRoute('home',{replace:true})}};
}

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))}
async function boot(){
 state.ui={loading:true};render();
 try{const r=await api.init();if(r.session){await afterLogin()}else{state.session=false;await refreshStats()}}catch(e){console.error(e)}
 state.ui.loading=false;
 const url=new URL(location.href);
 state.route=routeFromLocation();
 if(url.searchParams.get('paid')){toast(ax('adv_paid_ok'));await refreshAdvisory();state.route='marriage'}
 if(url.searchParams.get('verification')==='returned'){toast(ax('verify_returned'));if(!state.user.verificationStatus||state.user.verificationStatus==='Not Started')state.user.verificationStatus='In Progress';state.route='profile'}
 try{history.replaceState({route:state.route},'',routePath(state.route))}catch{}
 save();render();
 api.onAuthChange(has=>{if(!has&&state.session){state.session=false;profiles=[];matchProfiles=[];save();render()}});
}
boot();
